package com.hashem.sms; import android.app.*;import android.content.*;import android.os.*;import android.telephony.*;import java.util.ArrayList; public class HeadlessSmsSendService extends Service{public IBinder onBind(Intent i){return null;}public int onStartCommand(Intent i,int f,int id){if(i!=null){String a=i.getDataString(),b=i.getStringExtra(Intent.EXTRA_TEXT);if(a!=null&&b!=null){int subId=getSharedPreferences("sms_preferences",MODE_PRIVATE).getInt("subscription_id",-1);SmsManager sms=(Build.VERSION.SDK_INT>=22&&subId>=0)?SmsManager.getSmsManagerForSubscriptionId(subId):SmsManager.getDefault();ArrayList<String> parts=sms.divideMessage(b);sms.sendMultipartTextMessage(a.replace("sms:","").replace("smsto:",""),null,parts,null,null);}}return START_NOT_STICKY;}}
